#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
for f in event refund seat; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="?//; s/"$//; s/=.*//' | grep -q '[^A-Za-z0-9_.-]' && { echo "key $f"; fail=1; }
done
exit $fail

rc=0

